package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Owned API64 Time field fidelity contract.
func TestRunTimeFieldFidelity64(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"64.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB3TimeFidelity64.cls"), "@IsTest private class GladeB3TimeFidelity64 {\n private static ClockProbe__c row() {\n  return new ClockProbe__c(Name='fidelity', Day__c=Date.newInstance(2026,9,5), Clock__c=Time.newInstance(8,9,10,123));\n }\n private static void assertClock(Time value) {\n  System.assertEquals(8,value.hour()); System.assertEquals(9,value.minute());\n  System.assertEquals(10,value.second()); System.assertEquals(123,value.millisecond());\n }\n @IsTest static void assignedFieldComponents() { assertClock(row().Clock__c); }\n @IsTest static void queriedFieldComponents() {\n  ClockProbe__c value=row(); insert value;\n  ClockProbe__c loaded=[SELECT Day__c,Clock__c FROM ClockProbe__c WHERE Id=:value.Id];\n  assertClock(loaded.Clock__c);\n  System.assertEquals(2026,loaded.Day__c.year()); System.assertEquals(9,loaded.Day__c.month()); System.assertEquals(5,loaded.Day__c.day());\n }\n @IsTest static void typedLocalComponents() {\n  ClockProbe__c value=row(); insert value;\n  ClockProbe__c loaded=[SELECT Clock__c FROM ClockProbe__c WHERE Id=:value.Id];\n  Time clock=loaded.Clock__c; assertClock(clock);\n }\n @IsTest static void describeTimeField() {\n  System.assertEquals(Schema.DisplayType.TIME,ClockProbe__c.Clock__c.getDescribe().getType());\n }\n @IsTest static void updatedFieldComponents() {\n  ClockProbe__c value=row(); insert value; value.Clock__c=Time.newInstance(23,58,57,456); update value;\n  ClockProbe__c loaded=[SELECT Clock__c FROM ClockProbe__c WHERE Id=:value.Id];\n  System.assertEquals(23,loaded.Clock__c.hour()); System.assertEquals(58,loaded.Clock__c.minute());\n  System.assertEquals(57,loaded.Clock__c.second()); System.assertEquals(456,loaded.Clock__c.millisecond());\n }\n @IsTest static void clearedFieldIsNull() {\n  ClockProbe__c value=row(); insert value; value.Clock__c=null; update value;\n  ClockProbe__c loaded=[SELECT Clock__c FROM ClockProbe__c WHERE Id=:value.Id];\n  System.assertEquals(null,loaded.Clock__c);\n }\n @IsTest static void queriedConstructorCalendarComponents() {\n  ClockProbe__c value=row(); insert value;\n  ClockProbe__c loaded=[SELECT Day__c,Clock__c FROM ClockProbe__c WHERE Id=:value.Id];\n  Datetime combined=Datetime.newInstanceGmt(loaded.Day__c,loaded.Clock__c);\n  System.assertEquals(2026,combined.yearGmt()); System.assertEquals(9,combined.monthGmt()); System.assertEquals(5,combined.dayGmt());\n  System.assertEquals(8,combined.hourGmt()); System.assertEquals(9,combined.minuteGmt()); System.assertEquals(10,combined.secondGmt());\n }\n @IsTest static void timeFilterMatchesValue() {\n  ClockProbe__c first=row(); insert first;\n  ClockProbe__c second=row(); second.Clock__c=Time.newInstance(17,0,0,0); insert second;\n  Time expected=Time.newInstance(8,9,10,123);\n  List<ClockProbe__c> matches=[SELECT Id FROM ClockProbe__c WHERE Clock__c=:expected];\n  System.assertEquals(1,matches.size()); System.assertEquals(first.Id,matches[0].Id);\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB3TimeFidelity64.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>64.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/ClockProbe__c/ClockProbe__c.object-meta.xml"), "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><label>Clock Probe</label><pluralLabel>Clock Probes</pluralLabel><nameField><label>Name</label><type>Text</type></nameField><deploymentStatus>Deployed</deploymentStatus><sharingModel>ReadWrite</sharingModel></CustomObject>")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/ClockProbe__c/fields/Clock__c.field-meta.xml"), "<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>Clock__c</fullName><label>Clock__c</label><type>Time</type></CustomField>")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/ClockProbe__c/fields/Day__c.field-meta.xml"), "<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>Day__c</fullName><label>Day__c</label><type>Date</type></CustomField>")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 8 || got.Passed != 8 {
		data, _ := json.Marshal(run)
		t.Fatalf("Time fidelity cases failed: %s", data)
	}
}

